  ?zone rdfs:label "Perimeter_mid_ZN_4" .
  ?temp_sensor brick:isPointOf ?zone, brick:zoneAirTemperature .
  ?heat_setpoint brick:isPointOf ?zone, brick:zoneHeatingSetpoint .
  ?cool_setpoint brick:isPointOf ?zone, brick:zoneCoolingSetpoint .
}

SELECT ?point ?ts_id WHERE {
  VALUES ?point { 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05.Zone_Air_Cooling_Temperature_Setpoint> 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05.Zone_Air_Heating_Temperature_Setpoint> 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05.Zone_Air_Temperature_Sensor> 
  }
  { ?point ref:hasTimeseriesId ?ts_id } UNION { ?point ref:hasExternalReference ?ts_id }
}

