import csv

# The urns from query_graph
cooling_urn = 'urn:buildgraph:tsref:c9fc3c98-8ad8-5bba-a072-0a5c02357f48'
heating_urn = 'urn:buildgraph:tsref:dcb57f97-6711-5249-9f6f-3a81a69fc8d6'
temp_urn = 'urn:buildgraph:tsref:c49bbc2f-096e-5e16-bead-066250790308'

# Extract the UUID part
def extract_id(urn):
    return urn.replace('urn:buildgraph:tsref:', '')

cooling_id = extract_id(cooling_urn)
heating_id = extract_id(heating_urn)
temp_id = extract_id(temp_urn)

date_str = '2018-07-04'

data = {}
with open(VALUES_CSV, 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ts_id = row['timeseries_id']
        if ts_id in [cooling_id, heating_id, temp_id]:
            if row['timestamp'].startswith(date_str):
                if ts_id not in data:
                    data[ts_id] = {}
                data[ts_id][row['timestamp']] = float(row['value'])

if not data:
    print("No data found for the specified date and IDs.")
else:
    timestamps = set()
    for tid in data:
        timestamps.update(data[tid].keys())

    sorted_ts = sorted(list(timestamps))
    all_within = True

    for t in sorted_ts:
        temp = data.get(temp_id, {}).get(t)
        heat = data.get(heating_id, {}).get(t)
        cool = data.get(cooling_id, {}).get(t)

        if temp is None or heat is None or cool is None:
            print(f"Missing value at {t}: temp={temp}, heat={heat}, cool={cool}")
            all_within = False
            break

        # Condition: Heat Setpoint <= Temperature <= Cool Setpoint
        if not (heat <= temp <= cool):
            print(f"Out of range at {t}: temp={temp}, heat={heat}, cool={cool}")
            all_within = False
            break

    print(f"RESULT: {all_within}")
